package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct { // 01 AMT-REC, 11 bytes
	ArAcct string          // PIC X(4) @0 len=4
	ArAmt  decimal.Decimal // PIC 9(5)V99 @4 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                 // PIC X len=1 = "N"
var WsBigTotal decimal.Decimal             // PIC 9(7)V99 len=9 = 0
var WsWrapTotal decimal.Decimal            // PIC 9(5)V99 len=7 = 0
var WsSafeTotal decimal.Decimal            // PIC 9(5)V99 len=7 = 0
var WsOverflows int64 = 0                  // PIC 99 len=2 = 0
var WsCount int64 = 0                      // PIC 99 len=2 = 0
var WsHalf decimal.Decimal                 // PIC 9(5)V9 len=6 = 0
var WsAmtEd string                         // PIC ZZ,ZZ9.99 len=9
var WsWrapEd string                        // PIC ZZ,ZZ9.99 len=9
var WsSafeEd string                        // PIC ZZ,ZZ9.99 len=9
var WsHalfEd string                        // PIC ZZ,ZZ9.9 len=8

var amtRec AmtRec
var inputLines []string
var inputIndex int

func isInputDone() bool { return WsEofFlag == "Y" }

func pow10Int64(n int) int64 {
	var v int64 = 1
	for i := 0; i < n; i++ {
		v *= 10
	}
	return v
}

func truncateToPic(val decimal.Decimal, intDigits, scale int) decimal.Decimal {
	total := intDigits + scale
	shifted := val.Shift(int32(scale))
	unscaled := shifted.Truncate(0)
	modInt := pow10Int64(total)
	vi := unscaled.IntPart()
	if vi >= 0 {
		vi = vi % modInt
	} else {
		vi = -((-vi) % modInt)
	}
	return decimal.New(vi, int32(-scale))
}

func moveNumeric(src decimal.Decimal, srcInt, srcScale, destInt, destScale int) decimal.Decimal {
	// MOVE with high-order truncation
	shifted := src.Shift(int32(destScale))
	unscaled := shifted.Truncate(0)
	total := destInt + destScale
	modInt := pow10Int64(total)
	vi := unscaled.IntPart()
	if vi >= 0 {
		vi = vi % modInt
	} else {
		vi = -((-vi) % modInt)
	}
	return decimal.New(vi, int32(-destScale))
}

func addTruncate(dest, addend decimal.Decimal, intDigits, scale int) decimal.Decimal {
	sum := dest.Add(addend)
	return truncateToPic(sum, intDigits, scale)
}

func wouldOverflow(dest, addend decimal.Decimal, intDigits, scale int) bool {
	total := intDigits + scale
	maxUnscaled := pow10Int64(total) - 1
	max := decimal.New(maxUnscaled, int32(-scale))
	sum := dest.Add(addend)
	if sum.GreaterThan(max) {
		return true
	}
	if sum.IsNegative() { // unsigned PIC 9
		return true
	}
	return false
}

func addIntTruncate(cur, add int64, digits int) int64 {
	mod := pow10Int64(digits)
	return (cur + add) % mod
}

func formatPIC99(v int64) string {
	mod := pow10Int64(2)
	v = v % mod
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%02d", v)
}

func formatEdited(val decimal.Decimal, pic string) string {
	var intPic, decPic string
	if idx := strings.Index(pic, "."); idx >= 0 {
		intPic = pic[:idx]
		decPic = pic[idx+1:]
	} else {
		intPic = pic
	}
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	decDigits := 0
	for _, ch := range decPic {
		if ch == 'Z' || ch == '9' {
			decDigits++
		}
	}
	totalDigits := intDigits + decDigits
	shifted := val.Shift(int32(decDigits))
	unscaled := shifted.Truncate(0)
	modInt := pow10Int64(totalDigits)
	vi := unscaled.IntPart()
	if vi >= 0 {
		vi = vi % modInt
	} else {
		vi = -((-vi) % modInt)
	}
	absVi := vi
	if absVi < 0 {
		absVi = -absVi
	}
	powDec := pow10Int64(decDigits)
	var intPart int64
	var decPart int64
	if decDigits > 0 {
		intPart = absVi / powDec
		decPart = absVi % powDec
	} else {
		intPart = absVi
	}
	// build integer digits array
	digits := make([]int, intDigits)
	tmp := intPart
	for i := intDigits - 1; i >= 0; i-- {
		digits[i] = int(tmp % 10)
		tmp /= 10
	}
	var b strings.Builder
	dIdx := 0
	seen := false
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			d := digits[dIdx]
			dIdx++
			if ch == '9' {
				b.WriteByte(byte('0' + d))
				if d != 0 {
					seen = true
				}
			} else { // Z
				if seen || d != 0 {
					b.WriteByte(byte('0' + d))
					seen = true
				} else {
					b.WriteByte(' ')
				}
			}
		} else if ch == ',' {
			if seen {
				b.WriteByte(',')
			} else {
				b.WriteByte(' ')
			}
		} else {
			b.WriteRune(ch)
		}
	}
	if decDigits > 0 {
		decStr := fmt.Sprintf("%0*d", decDigits, decPart)
		return b.String() + "." + decStr
	}
	return b.String()
}

// paragraph functions

func openInput() {
	f, err := os.Open("input.dat")
	if err != nil {
		inputLines = []string{}
		return
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	// allow preserving trailing spaces - Scanner keeps them
	for sc.Scan() {
		line := sc.Text()
		inputLines = append(inputLines, line)
	}
	if err := sc.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "read error: %v\n", err)
		os.Exit(1)
	}
}

func closeInput() {}

func readPara() {
	if inputIndex >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIndex]
	inputIndex++
	if len(line) < 11 {
		line = line + strings.Repeat(" ", 11-len(line))
	} else if len(line) > 11 {
		line = line[:11]
	}
	amtRec.ArAcct = line[0:4]
	rawAmt := line[4:11]
	digits := ""
	for _, ch := range rawAmt {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		} else {
			digits += "0"
		}
	}
	if digits == "" {
		digits = "0000000"
	}
	n, _ := strconv.ParseInt(digits, 10, 64)
	amtRec.ArAmt = decimal.New(n, -2)
}

func overflowPara() {
	WsOverflows = addIntTruncate(WsOverflows, 1, 2)
}

func processPara() {
	// ADD AR-AMT TO WS-BIG-TOTAL
	WsBigTotal = addTruncate(WsBigTotal, amtRec.ArAmt, 7, 2)
	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL
	WsWrapTotal = moveNumeric(WsBigTotal, 7, 2, 5, 2)
	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA END-ADD
	// Due to nested ADD ... END-ADD ambiguity the statements after END-ADD
	// belong to the SIZE ERROR branch.  The READ that terminates the
	// paragraph is a separate sentence and is executed unconditionally
	// (period after DISPLAY ends the SIZE ERROR sentence).
	if wouldOverflow(WsSafeTotal, amtRec.ArAmt, 5, 2) {
		overflowPara()
		// following statements are inside ON SIZE ERROR
		WsCount = addIntTruncate(WsCount, 1, 2)
		halfExact := amtRec.ArAmt.Div(decimal.NewFromInt(2))
		WsHalf = halfExact.Truncate(1)
		WsHalf = truncateToPic(WsHalf, 5, 1)
		WsAmtEd = formatEdited(amtRec.ArAmt, "ZZ,ZZ9.99")
		WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
		WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
		WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")
		fmt.Printf("%s %s %s %s %s\n", amtRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	} else {
		WsSafeTotal = WsSafeTotal.Add(amtRec.ArAmt)
		// when no SIZE ERROR the inside-branch statements are skipped
	}
	readPara()
}

func summaryPara() {
	fmt.Printf("RECORDS: %s\n", formatPIC99(WsCount))
	fmt.Printf("OVERFLOWS: %s\n", formatPIC99(WsOverflows))
}

func mainPara() {
	openInput()
	readPara()
	for !isInputDone() {
		processPara()
	}
	closeInput()
	summaryPara()
}

func main() {
	mainPara()
}

